import{_ as l,o as a,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph User + Developer Monthly Meeting 2024-11-20","description":"","frontmatter":{"title":"Ceph User + Developer Monthly Meeting 2024-11-20","date":"2024-11-20T00:00:00.000Z","updated":"2024-11-21T00:00:00.000Z","tags":["Ceph","用户案例","成功故事","分布式存储","社区协作"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_User_+_Developer_Monthly_Meeting_2024-11-20.md","filePath":"posts/2024/Ceph_User_+_Developer_Monthly_Meeting_2024-11-20.md","lastUpdated":1780459816000}'),o={name:"posts/2024/Ceph_User_+_Developer_Monthly_Meeting_2024-11-20.md"};function i(h,e,n,s,p,_){return a(),t("div",null,[...e[0]||(e[0]=[r('<h3 id="ceph-用户与开发者月度会议纪要" tabindex="-1">Ceph 用户与开发者月度会议纪要 <a class="header-anchor" href="#ceph-用户与开发者月度会议纪要" aria-label="Permalink to &quot;Ceph 用户与开发者月度会议纪要&quot;">​</a></h3><p><strong>日期</strong>: 2024年11月20日<br><strong>主持人</strong>: Laura<br><strong>参会人员</strong>: Laura, N, Gorav, 以及其他 Ceph 用户和开发者</p><h4 id="会议主题" tabindex="-1">会议主题: <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题:&quot;">​</a></h4><p>本次会议主要讨论了如何收集和展示 Ceph 的用户案例和成功故事，以推动 Ceph 社区的协作与创新。</p><h4 id="讨论内容" tabindex="-1">讨论内容: <a class="header-anchor" href="#讨论内容" aria-label="Permalink to &quot;讨论内容:&quot;">​</a></h4><ol><li><p><strong>用户案例和成功故事的收集</strong>:</p><ul><li>由于 Ceph 技术的快速发展，现有的用户案例和成功故事大多已过时。社区计划通过新的方式收集更多当前的用户案例，特别是关于大规模生产环境的使用情况。</li><li>目标是收集并展示 Ceph 在大规模生产环境中的创新使用案例，特别是涉及高扩展性和多工作负载的应用场景。</li><li>方法是通过向 Ceph 用户社区分发调查问卷，收集用户的使用案例，并将这些案例展示在 Ceph 官方网站上。</li></ul></li><li><p><strong>调查问卷的设计</strong>:</p><ul><li>问卷将涵盖用户组织的基本信息、Ceph 的使用场景、存储的数据类型、面临的挑战、Ceph 带来的好处等。</li><li>重点在于除了应用层的使用情况，社区还希望了解用户在设置和维护 Ceph 集群过程中遇到的挑战和成功经验。</li></ul></li><li><p><strong>用户反馈的重要性</strong>:</p><ul><li>开发者需要了解用户如何使用 Ceph，以便更好地设计和测试新功能。用户的反馈可以帮助开发者识别潜在的问题，并改进产品。</li><li>通过分享用户案例，社区成员可以相互学习，丰富 Ceph 的使用知识和经验。</li></ul></li><li><p><strong>隐私与敏感信息的处理</strong>:</p><ul><li>问卷中的所有问题都是可选的，用户可以选择不分享敏感信息。社区鼓励用户分享尽可能多的信息，尤其是那些可以帮助其他用户解决类似问题的经验。</li><li>即使无法分享具体的公司或项目信息，用户也可以提供通用的反馈，如集群规模、性能特征等。</li></ul></li><li><p><strong>未来计划</strong>:</p><ul><li>该计划将作为一个持续的项目，定期收集和展示用户案例。</li><li>调查问卷将在未来几周内发布，用户可以在收到问卷后开始准备分享他们的使用案例。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项: <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项:&quot;">​</a></h4><ol><li><strong>发布调查问卷</strong>: 在未来几周内，Ceph 社区将通过邮件列表、Slack 和社交媒体发布用户案例调查问卷。</li><li><strong>收集用户反馈</strong>: 用户可以开始思考他们的 Ceph 使用案例，特别是那些涉及大规模生产环境的案例，并准备分享相关的挑战和成功经验。</li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划: <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划:&quot;">​</a></h4><ol><li><strong>发布调查问卷</strong>: 预计在未来几周内发布调查问卷，并通过邮件列表、Slack 和社交媒体通知用户。</li><li><strong>收集用户案例</strong>: 用户在收到问卷后，可以开始填写并提交他们的使用案例。</li><li><strong>展示用户案例</strong>: 收集到的用户案例将经过整理后，展示在 Ceph 官方网站上，特别是在 CephCon 等社区活动中进行推广。</li></ol><h4 id="其他讨论" tabindex="-1">其他讨论: <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论:&quot;">​</a></h4><ul><li><strong>Ceph 升级体验的改进</strong>: 用户 Alex 分享了 Ceph 升级体验的显著改善，特别是最近的升级过程中没有出现任何回归问题，这得益于社区在升级测试和工具方面的持续改进。</li><li><strong>未来版本发布的时间线</strong>: 用户询问了关于 Ceph 未来版本发布的时间线和主要功能的更新。社区表示，未来版本的发布计划将在 Ceph 的领导团队会议上讨论，并会在社区日历和 Etherpad 上公布相关信息。</li></ul><h4 id="会议总结" tabindex="-1">会议总结: <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结:&quot;">​</a></h4><p>本次会议讨论了如何通过收集和展示 Ceph 用户案例来推动社区协作与创新。Ceph 社区计划在未来几周内发布调查问卷，收集用户的使用案例，并将其展示在官方网站上。开发者和其他社区成员可以通过这些案例了解 Ceph 的实际使用情况，并从中学习。</p><h4 id="下次会议" tabindex="-1">下次会议: <a class="header-anchor" href="#下次会议" aria-label="Permalink to &quot;下次会议:&quot;">​</a></h4><p>预计在下个月的同一时间举行，届时将讨论更多关于 Ceph 用户案例的进展。</p>',16)])])}const u=l(o,[["render",i]]);export{g as __pageData,u as default};
